-- Bug: unqualified `id` in these policies resolved to program_assignments.id /
-- meal_plan_assignments.id, so clients could never read their assigned versions.
drop policy "client read assigned versions" on public.program_versions;
create policy "client read assigned versions" on public.program_versions for select using (
 exists (select 1 from public.program_assignments a
 where a.version_id = program_versions.id and a.client_id = auth.uid())
);

drop policy "client read assigned mp versions" on public.meal_plan_versions;
create policy "client read assigned mp versions" on public.meal_plan_versions for select using (
 exists (select 1 from public.meal_plan_assignments a
 where a.version_id = meal_plan_versions.id and a.client_id = auth.uid())
);

-- Builder v2: week-agnostic days + progression overrides + library templates
alter table public.programs
 add column if not exists description text,
 add column if not exists is_template boolean not null default false,
 add column if not exists source_program_id uuid references public.programs(id),
 add column if not exists weeks int not null default 4,
 add column if not exists days_per_week int not null default 3;

alter table public.block_exercises add column if not exists directions text;

create table public.program_week_overrides (
 id uuid primary key default gen_random_uuid(),
 block_exercise_id uuid not null references public.block_exercises(id) on delete cascade,
 week int not null,
 sets int,
 rep_range text,
 target_weight_lbs numeric,
 unique (block_exercise_id, week)
);
alter table public.program_week_overrides enable row level security;
create policy "admin all pwo" on public.program_week_overrides for all using (public.is_admin()) with check (public.is_admin());
create policy "client read assigned pwo" on public.program_week_overrides for select using (
 exists (select 1 from public.block_exercises be
 join public.day_blocks b on b.id = be.block_id
 join public.program_days d on d.id = b.day_id
 join public.program_assignments a on a.version_id = d.version_id
 where be.id = program_week_overrides.block_exercise_id and a.client_id = auth.uid())
);

-- Meal plans: description, template, targets
alter table public.meal_plans
 add column if not exists description text,
 add column if not exists is_template boolean not null default false,
 add column if not exists source_meal_plan_id uuid references public.meal_plans(id),
 add column if not exists target_calories numeric,
 add column if not exists target_mode text not null default 'percent' check (target_mode in ('percent','grams')),
 add column if not exists target_protein_g numeric,
 add column if not exists target_carbs_g numeric,
 add column if not exists target_fat_g numeric,
 add column if not exists target_protein_pct numeric,
 add column if not exists target_carbs_pct numeric,
 add column if not exists target_fat_pct numeric;

-- Nicole's cached food library
create table public.foods (
 id uuid primary key default gen_random_uuid(),
 name text not null,
 portion_label text not null default '',
 portion_grams numeric,
 calories numeric not null default 0,
 protein numeric not null default 0,
 carbs numeric not null default 0,
 fats numeric not null default 0,
 source text not null default 'manual' check (source in ('usda','ai','manual')),
 usda_fdc_id text,
 created_at timestamptz not null default now()
);
alter table public.foods enable row level security;
create policy "admin all foods" on public.foods for all using (public.is_admin()) with check (public.is_admin());
create policy "clients read foods" on public.foods for select using (auth.uid() is not null);

-- Client meal check-offs
create table public.meal_checkoffs (
 id uuid primary key default gen_random_uuid(),
 client_id uuid not null references public.profiles(id) on delete cascade,
 log_date date not null default current_date,
 meal_id uuid not null references public.meals(id) on delete cascade,
 status text not null check (status in ('ate_as_written','custom')),
 created_at timestamptz not null default now(),
 unique (client_id, log_date, meal_id)
);
create table public.meal_checkoff_items (
 id uuid primary key default gen_random_uuid(),
 checkoff_id uuid not null references public.meal_checkoffs(id) on delete cascade,
 client_id uuid not null references public.profiles(id) on delete cascade,
 meal_item_id uuid references public.meal_items(id) on delete set null,
 name text not null,
 calories numeric not null default 0,
 protein numeric not null default 0,
 carbs numeric not null default 0,
 fats numeric not null default 0
);
alter table public.meal_checkoffs enable row level security;
alter table public.meal_checkoff_items enable row level security;
create policy "admin all mco" on public.meal_checkoffs for all using (public.is_admin()) with check (public.is_admin());
create policy "admin all mcoi" on public.meal_checkoff_items for all using (public.is_admin()) with check (public.is_admin());
create policy "client own mco" on public.meal_checkoffs for all using (client_id = auth.uid()) with check (client_id = auth.uid());
create policy "client own mcoi" on public.meal_checkoff_items for all using (client_id = auth.uid()) with check (client_id = auth.uid());

-- Food journal entries gain macros
alter table public.food_logs
 add column if not exists calories numeric,
 add column if not exists protein numeric,
 add column if not exists carbs numeric,
 add column if not exists fats numeric;

-- Messaging media
alter table public.messages
 add column if not exists kind text not null default 'text' check (kind in ('text','voice','video')),
 add column if not exists media_path text,
 add column if not exists duration_seconds numeric;

insert into storage.buckets (id, name, public) values ('message-media','message-media', false)
on conflict (id) do nothing;
create policy "msg media own read" on storage.objects for select
 using (bucket_id = 'message-media' and (public.is_admin() or (storage.foldername(name))[1] = auth.uid()::text));
create policy "msg media own insert" on storage.objects for insert
 with check (bucket_id = 'message-media' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));

-- Check-in v2
alter table public.checkins
 add column if not exists energy_rating int check (energy_rating between 1 and 5),
 add column if not exists focus_next_week text,
 add column if not exists late boolean not null default false;

create table public.checkin_reopens (
 id uuid primary key default gen_random_uuid(),
 client_id uuid not null references public.profiles(id) on delete cascade,
 iso_week text not null,
 created_at timestamptz not null default now(),
 unique (client_id, iso_week)
);
alter table public.checkin_reopens enable row level security;
create policy "admin all reopens" on public.checkin_reopens for all using (public.is_admin()) with check (public.is_admin());
create policy "client read own reopens" on public.checkin_reopens for select using (client_id = auth.uid());
